INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7189501, 1104852, 28742, '<td valign="top">You are just AWESOME, Katie.</td>', 'You are just AWESOME, Katie.', '2014-03-14 01:29:13.000000', NULL, 0),
(7189505, 1105055, 68413, '<td valign="top">Well done Alex. Brilliant concept and very well executed.<br/>I can''t for the life of me figure out how any moron could give this a one....</td>', 'Well done Alex. Brilliant concept and very well executed.I can''t for the life of me figure out how any moron could give this a one....', '2014-03-14 01:37:02.000000', NULL, 0),
(7189514, 1105040, 137091, '<td valign="top">Congrats on the baby :-)</td>', 'Congrats on the baby :-)', '2014-03-14 02:35:35.000000', NULL, 0),
(7189517, 1104987, 68413, '<td valign="top">Makes me chuckle</td>', 'Makes me chuckle', '2014-03-14 02:47:00.000000', NULL, 0),
(7189519, 1105040, 129807, '<td valign="top">Wowowowowowowowowowowowowwwww!!! Christophe! I just read your story......... CONGRATULATIONS!!!</td>', 'Wowowowowowowowowowowowowwwww!!! Christophe! I just read your story......... CONGRATULATIONS!!!', '2014-03-14 02:53:50.000000', NULL, 0),
(7189522, 1105040, 58667, '<td valign="top">Cool story! Congratulations! Pregnancy isn''t easy, but it''s only 9 months - they seem to go slowly, but they actually fly. As horrible as it can be, take it in and enjoy it. It''s such a defining and beautiful part of life.</td>', 'Cool story! Congratulations! Pregnancy isn''t easy, but it''s only 9 months - they seem to go slowly, but they actually fly. As horrible as it can be, take it in and enjoy it. It''s such a defining and beautiful part of life.', '2014-03-14 03:06:44.000000', NULL, 0),
(7189529, 1105040, 100393, '<td valign="top">I never looked at this challenge during voting but noticed this on the front page.<br/> <br/>As you know I''m a fan of your work, because of the communication of process along with the final product.<br/> <br/>Here though, you have surpassed yourself - I think this is the best image I''ve seen from you; as ever it has supreme clarity and technical mastery but what shines through are things like tenderness, beauty and vulnerability. I found the paper tears in the skin quite moving but the stoic expression and the rays of light from the top right communicate a sense of strength and even peace. All of this from an image that could easily have channeled violence and dread.<br/> <br/>We are used to the quality of your work by now and your mastery of Photoshop is so consistent that we do perhaps take it for granted. For me, it''s important that we continue to take the time to look at your work with fresh eyes from time to time and reconnect with the artistic and visionary process that underpins it.<br/> <br/>As you know, I''m a fan of blur, of low fidelity, of street, of black and white - frequently favouring such in my own commenting, but I also really value your pristine, colourful and necessarily contrived art - where others create through reinterpreting the real world, overlaying grain, pushing contrast and creating through the constraining of a scene (or moment), you create your own - it''s another, and wholly legitimate, route to creating photographic art - and here, for me, you''ve demonstrated how emotive, personal and powerful that can be.<br/> <br/>I very much value your contributions here at DPC - you''ve raised the bar for such high fidelity work so effortlessly that I think we sometimes forget the contribution you have made to changing the expectations of this small community in relation to such work.<br/> <br/>I for one want to acknowledge that, to say thank you and to pass on a hope that you keep submitting and allow us to enjoy both your creations and the creative process that is so central to your work.<br/> <br/>Thank you.<br/> <br/>I read the accompanying piece too - congratulations!</td>', 'I never looked at this challenge during voting but noticed this on the front page. As you know I''m a fan of your work, because of the communication of process along with the final product. Here though, you have surpassed yourself - I think this is the best image I''ve seen from you; as ever it has supreme clarity and technical mastery but what shines through are things like tenderness, beauty and vulnerability. I found the paper tears in the skin quite moving but the stoic expression and the rays of light from the top right communicate a sense of strength and even peace. All of this from an image that could easily have channeled violence and dread. We are used to the quality of your work by now and your mastery of Photoshop is so consistent that we do perhaps take it for granted. For me, it''s important that we continue to take the time to look at your work with fresh eyes from time to time and reconnect with the artistic and visionary process that underpins it. As you know, I''m a fan of blur, of low fidelity, of street, of black and white - frequently favouring such in my own commenting, but I also really value your pristine, colourful and necessarily contrived art - where others create through reinterpreting the real world, overlaying grain, pushing contrast and creating through the constraining of a scene (or moment), you create your own - it''s another, and wholly legitimate, route to creating photographic art - and here, for me, you''ve demonstrated how emotive, personal and powerful that can be. I very much value your contributions here at DPC - you''ve raised the bar for such high fidelity work so effortlessly that I think we sometimes forget the contribution you have made to changing the expectations of this small community in relation to such work. I for one want to acknowledge that, to say thank you and to pass on a hope that you keep submitting and allow us to enjoy both your creations and the creative process that is so central to your work. Thank you. I read the accompanying piece too - congratulations!', '2014-03-14 03:25:57.000000', NULL, 0),
(7189537, 1104987, 159196, '<td valign="top">Congrats!</td>', 'Congrats!', '2014-03-14 03:41:42.000000', NULL, 0),
(7189542, 1105046, 82707, '<td valign="top">''Grats Stag!  Great image!  :)</td>', '''Grats Stag!  Great image!  :)', '2014-03-14 03:51:49.000000', NULL, 0),
(7189546, 1105040, 114285, '<td valign="top">So glad you will finally experience life with a child, very happy for you. I was only thinking today what it would like  if you had a child and if you ever would incorporate him/her in any of your photos, and then I read your blog, congratulations to both of you; and I do hope her pregnancy goes well.<br/> <br/>I have to admit those charred fingers freaked me out!!<br/><br/><i>Message edited by author 2014-03-14 04:16:10.</i></td>', 'So glad you will finally experience life with a child, very happy for you. I was only thinking today what it would like  if you had a child and if you ever would incorporate him/her in any of your photos, and then I read your blog, congratulations to both of you; and I do hope her pregnancy goes well. I have to admit those charred fingers freaked me out!!', '2014-03-14 04:15:35.000000', '2014-03-14 04:16:10.000000', 0),
(7189550, 1105055, 127021, '<td valign="top">Congrats Alex! Great idea and execution...</td>', 'Congrats Alex! Great idea and execution...', '2014-03-14 04:41:47.000000', NULL, 0),
(7189551, 1105040, 127021, '<td valign="top">Huge congratulations Christophe for everything!!!</td>', 'Huge congratulations Christophe for everything!!!', '2014-03-14 04:47:03.000000', NULL, 0),
(7189552, 1104711, 127021, '<td valign="top">Congrats on your first ribbon!!!</td>', 'Congrats on your first ribbon!!!', '2014-03-14 04:47:36.000000', NULL, 0),
(7189553, 1105040, 20799, '<td valign="top">Congratulations Christophe!!! My best wishes to both of you - or rather, to the three of you :-).<br/>Btw I hope you didn''t use this storytelling to break the news to your family. It starts off really scary, you can give someone a heart attack! :)<br/> <br/>The image is undoubtedly one of your best. IMHO, looking at this as a concept, I would have stayed at two arms. The whole setup - the angle, look, fire, the constraining black hands are already so striking and at least for me, less would give more impact - just my two cents. Congrats on the ribbon!</td>', 'Congratulations Christophe!!! My best wishes to both of you - or rather, to the three of you :-).Btw I hope you didn''t use this storytelling to break the news to your family. It starts off really scary, you can give someone a heart attack! :) The image is undoubtedly one of your best. IMHO, looking at this as a concept, I would have stayed at two arms. The whole setup - the angle, look, fire, the constraining black hands are already so striking and at least for me, less would give more impact - just my two cents. Congrats on the ribbon!', '2014-03-14 04:48:07.000000', NULL, 0),
(7189555, 1105054, 20799, '<td valign="top">Wackiest of them all, I love this! You should eat more at that restaurant of yours :).</td>', 'Wackiest of them all, I love this! You should eat more at that restaurant of yours :).', '2014-03-14 04:50:11.000000', NULL, 0),
